/**
 * The Settings window on its first page, General → Appearance, ported from
 * the app's SettingsHub and SettingsMenu (src/panels/SettingsHub.tsx,
 * SettingsMenu.tsx: AppearanceSection, with ThemeSelect from ThemeSettings.tsx
 * and the Slider from src/ui/Slider.tsx) in the default state: the PzzaCode
 * theme, spacing at its default 10px and semi-transparent mode on.
 */
import type { CSSProperties, ReactNode } from "react";
import { ChevronDown } from "lucide-react";
import { SettingsWindow } from "./SettingsWindow";

/* The PzzaCode theme (src/theme/themes.ts): its terminal background, text and
   colors, and the border its chrome derives (the scene root's --border). */
const PZZACODE_THEME = {
  background: "#0b0e14",
  foreground: "#bfbdb6",
  border: "#36383b",
  colors: ["#ea6c73", "#f9af4f", "#91b362", "#90e1c6", "#53bdfa", "#fae994"],
};

/** ThemeSettings' Swatch: the theme's text on its background over a strip of its colors. */
function Swatch() {
  const theme = PZZACODE_THEME;
  return (
    <span className="theme-swatch" style={{ background: theme.background, borderColor: theme.border, color: theme.foreground }} aria-hidden="true">
      Aa
      <span className="theme-swatch-strip">
        {theme.colors.map((color, index) => (
          <i key={index} style={{ background: color }} />
        ))}
      </span>
    </span>
  );
}

/** SettingsMenu's Row. */
function Row({ label, hint, children }: { label: string; hint?: string; children: ReactNode }) {
  return (
    <div className="set-row">
      <div className="set-label">
        <span>{label}</span>
        {hint ? <span className="set-hint">{hint}</span> : null}
      </div>
      <div className="set-control">{children}</div>
    </div>
  );
}

function Switch({ on, label }: { on: boolean; label: string }) {
  return (
    <button className={`switch ${on ? "switch-on" : ""}`} type="button" role="switch" aria-label={label} aria-checked={on}>
      <span className="switch-knob" />
    </button>
  );
}

/** The app's Slider at `value`, with the default marked on its track. */
function Slider({ label, min, max, value, unit, mark }: { label: string; min: number; max: number; value: number; unit: string; mark: number }) {
  const ratio = (at: number) => (at - min) / Math.max(1, max - min);
  const track = { "--fill": `${ratio(value) * 100}%`, "--mark-ratio": String(ratio(mark)) } as CSSProperties;
  const shown = `${value}${unit}`;
  return (
    <span className="set-slider">
      <span className="set-slider-track" style={track}>
        <input aria-label={label} type="range" min={min} max={max} step={1} value={value} aria-valuetext={shown} readOnly />
        <span className={`set-slider-mark ${value === mark ? "is-on" : ""}`} title="Default" aria-hidden="true" />
      </span>
      <output className="set-slider-value" aria-hidden="true">
        {shown}
      </output>
    </span>
  );
}

function AppearancePage() {
  return (
    <div className="settings-page general-settings">
      <section className="set-section settings-section" aria-label="Appearance">
        <h3 className="set-title">Appearance</h3>
        <Row label="Theme" hint="Move through the list to see each theme on the whole app">
          <button type="button" className="cselect  theme-select" aria-label="Theme" aria-haspopup="listbox" aria-expanded={false}>
            <Swatch />
            <span className="cselect-value">PzzaCode</span>
            <ChevronDown size={14} className="muted-icon " />
          </button>
        </Row>
        <Row label="Grayscale mode" hint="Neutral gray interface; status and terminal colors stay">
          <Switch on={false} label="Grayscale mode" />
        </Row>
        <Row label="Spacing" hint="Room around and between tiles; 0 joins them edge to edge. The mark is the default.">
          {/* SPACING_RANGE in src/state/store.ts: 0 to 24px, default 10px. */}
          <Slider label="Spacing" min={0} max={24} value={10} unit="px" mark={10} />
        </Row>
        <Row label="Semi-transparent mode" hint="Translucent surfaces and a blurred background">
          <Switch on label="Semi-transparent mode" />
        </Row>
        <details className="settings-disclosure transparency-details">
          <summary>Transparency controls</summary>
        </details>
      </section>
    </div>
  );
}

export function SettingsShot() {
  return (
    <SettingsWindow section="general" page="appearance">
      <AppearancePage />
    </SettingsWindow>
  );
}
